import java.util.*;

public class Main {
    String addBinary(String a, String b) {
        long x = Long.parseLong(a, 2);                 // convert the first binary string to an integer
        long y = Long.parseLong(b, 2);                 // convert the second binary string to an integer
        return Long.toBinaryString(x + y);              // add them, then format the sum back as binary
    }

    public static void main(String[] args) {
        String a = "11", b = "1";
        Main solution = new Main();
        System.out.println(solution.addBinary(a, b));
    }
}

