#include <bits/stdc++.h>
using namespace std;

string addBinary(string a, string b) {
    long long x = stoll(a, nullptr, 2);             // convert the first binary string to an integer
    long long y = stoll(b, nullptr, 2);             // convert the second binary string to an integer
    long long sum = x + y;
    if (sum == 0) return "0";
    string result;
    while (sum > 0) {
        result += (char) ('0' + (sum % 2));            // peel off one binary digit at a time
        sum /= 2;
    }
    reverse(result.begin(), result.end());
    return result;
}

int main() {
    string a = "11", b = "1";
    cout << addBinary(a, b) << endl;
    return 0;
}

