def add_binary(a, b):
    i, j = len(a) - 1, len(b) - 1              # start at the last digit of each string
    carry = 0
    result = []
    while i >= 0 or j >= 0 or carry:
        total = carry
        if i >= 0:
            total += int(a[i])                     # add this digit from a, if any remain
            i -= 1
        if j >= 0:
            total += int(b[j])                     # add this digit from b, if any remain
            j -= 1
        result.append(str(total % 2))             # the digit that belongs in this column
        carry = total // 2                         # whatever carries into the next column
    return "".join(reversed(result))


if __name__ == "__main__":
    a, b = "11", "1"
    print(add_binary(a, b))

