import java.util.*;

public class Main {
    String addBinary(String a, String b) {
        int i = a.length() - 1, j = b.length() - 1;    // start at the last digit of each string
        int carry = 0;
        StringBuilder result = new StringBuilder();
        while (i >= 0 || j >= 0 || carry != 0) {
            int total = carry;
            if (i >= 0) {
                total += a.charAt(i) - '0';                // add this digit from a, if any remain
                i--;
            }
            if (j >= 0) {
                total += b.charAt(j) - '0';                 // add this digit from b, if any remain
                j--;
            }
            result.append(total % 2);                     // the digit that belongs in this column
            carry = total / 2;                             // whatever carries into the next column
        }
        return result.reverse().toString();
    }

    public static void main(String[] args) {
        String a = "11", b = "1";
        Main solution = new Main();
        System.out.println(solution.addBinary(a, b));
    }
}

